return (async () => {
const env = typeof process !== 'undefined' ? process.env : {};
const supabaseUrl = String(env.GROWICE_SUPABASE_URL || env.NEXT_PUBLIC_SUPABASE_URL || 'https://ugocvtuomyopullvilim.supabase.co').replace(/\/$/, '');
const supabaseKey = String(env.GROWICE_SUPABASE_SERVICE_ROLE || env.SUPABASE_SERVICE_ROLE_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InVnb2N2dHVvbXlvcHVsbHZpbGltIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3MjA5NzEyMiwiZXhwIjoyMDg3NjczMTIyfQ.d91fw0hhpwr7dPU33ixPeEWkNhonv-tO0h8DfM8wvbQ');
const smsApiKey = String(env.AEROSMS_API_KEY || 'SjsoV2kzDH1TyNfKcJ5DixA_aKLmh37t');
const smsLogin = String(env.AEROSMS_LOGIN || env.AEROSMS_EMAIL || '').trim();
const smsBasicAuth = String(env.AEROSMS_BASIC_AUTH || '').trim() || (smsLogin ? 'Basic ' + Buffer.from(`${smsLogin}:${smsApiKey}`).toString('base64') : '');
const smsSign = String(env.AEROSMS_SIGN || 'SMS Aero').trim() || 'SMS Aero';

const legacyWhatsAppConfig = {
  api_url: 'https://1105.api.green-api.com',
  instance_id: '1105555249',
  api_token: '0114f56bd3e247dd9bc0701418e128a81e495dc37c11430f8a'
};

const connectionCache = {};
const jsonHeaders = {
  apikey: supabaseKey,
  Authorization: `Bearer ${supabaseKey}`,
  Accept: 'application/json'
};

function isFalse(value) {
  if (value === false || value === 0) return true;
  const normalized = String(value ?? '').trim().toLowerCase();
  return ['false', '0', 'no', 'blocked', 'disconnected'].includes(normalized);
}

function canMessage(row) {
  return !isFalse(row?.blocked) && !isFalse(row?.can_message) && !isFalse(row?.allow_marketing);
}

function normalizePhone(value) {
  const digits = String(value ?? '').replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('8')) return `7${digits.slice(1)}`;
  if (digits.length === 10) return `7${digits}`;
  return digits;
}

function prettyName(row, fallback = 'Клиент') {
  const full = [row?.fullname, row?.first_name, row?.last_name].filter(Boolean).join(' ').trim();
  return full || fallback;
}

function encodeEq(value) {
  return encodeURIComponent(String(value));
}

function buildProviderUrl(config) {
  const apiUrl = String(config?.api_url || '').replace(/\/$/, '');
  const instanceId = String(config?.instance_id || '').trim();
  const apiToken = String(config?.api_token || '').trim();
  if (!apiUrl || !instanceId || !apiToken) return '';
  return `${apiUrl}/waInstance${instanceId}/sendMessage/${apiToken}`;
}

async function sbSelect(table, query) {
  const response = await fetch(`${supabaseUrl}/rest/v1/${table}?${query}`, { headers: jsonHeaders });
  const text = await response.text();
  const data = text ? JSON.parse(text) : [];
  if (!response.ok) {
    if (response.status === 404 || data?.code === 'PGRST205') return [];
    throw new Error(`Supabase ${table} ${response.status}: ${data?.message || text}`);
  }
  return Array.isArray(data) ? data : [];
}

async function getChannelConnection(channelCode) {
  if (Object.prototype.hasOwnProperty.call(connectionCache, channelCode)) {
    return connectionCache[channelCode];
  }
  const rows = await sbSelect(
    'channel_connections',
    `select=channel_code,status,instance_id,api_url,api_token,display_name,updated_at&channel_code=eq.${channelCode}&order=updated_at.desc.nullslast&limit=1`
  );
  connectionCache[channelCode] = rows[0] || null;
  return connectionCache[channelCode];
}

const [whatsAppConnection, maxConnection] = await Promise.all([
  getChannelConnection('whatsapp'),
  getChannelConnection('max')
]);

function pickGreenConfig(channel) {
  if (channel === 'whatsapp') {
    if (whatsAppConnection?.api_url && whatsAppConnection?.instance_id && whatsAppConnection?.api_token) {
      return whatsAppConnection;
    }
    return legacyWhatsAppConfig;
  }
  if (channel === 'max') {
    if (maxConnection?.api_url && maxConnection?.instance_id && maxConnection?.api_token) {
      return maxConnection;
    }
    if (env.MAX_GREEN_API_URL && env.MAX_GREEN_API_INSTANCE_ID && env.MAX_GREEN_API_TOKEN) {
      return {
        api_url: env.MAX_GREEN_API_URL,
        instance_id: env.MAX_GREEN_API_INSTANCE_ID,
        api_token: env.MAX_GREEN_API_TOKEN
      };
    }
  }
  return null;
}

function pushTarget(outputs, seen, target) {
  const recipient = String(target.recipient || '').trim();
  if (!recipient) return;
  const key = `${target.transport}:${recipient}`;
  if (seen.has(key)) return;
  seen.add(key);
  outputs.push({ json: target });
}

const outputs = [];

for (const item of items) {
  const source = item.json || {};
  const requestedChannels = Array.isArray(source.requested_channels) ? source.requested_channels : [];
  const requestedSet = new Set(requestedChannels);
  const recipientId = String(source.recipient_id || '').trim();
  if (!recipientId || requestedSet.size === 0) continue;

  const seen = new Set();
  const looksUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(recipientId);
  let client = null;

  if (looksUuid) {
    const clientRows = await sbSelect(
      'clients',
      `select=id,fullname,phone,yc_id&limit=1&id=eq.${encodeEq(recipientId)}`
    );
    client = clientRows[0] || null;
  }

  if (client) {
    const [clientChannels, telegramUsers, whatsappUsers, maxUsers] = await Promise.all([
      sbSelect('client_channels', `select=channel,channel_user_id,priority,is_active,can_notify&client_id=eq.${encodeEq(client.id)}&order=priority.asc`),
      sbSelect('telegram_users', `select=user_id,tg_username,first_name,last_name,blocked,allow_marketing,can_message&client_id=eq.${encodeEq(client.id)}`),
      sbSelect('whatsapp_users', `select=user_id,first_name,last_name,blocked,allow_marketing,can_message&client_id=eq.${encodeEq(client.id)}`),
      sbSelect('max_users', `select=user_id,first_name,last_name,blocked,allow_marketing,can_message&client_id=eq.${encodeEq(client.id)}`)
    ]);

    for (const row of clientChannels) {
      if (isFalse(row?.is_active) || isFalse(row?.can_notify)) continue;
      const mappedChannel = row.channel === 'phone' ? 'sms' : String(row.channel || '');
      if (!requestedSet.has(mappedChannel)) continue;

      if (mappedChannel === 'telegram') {
        pushTarget(outputs, seen, {
          campaign_name: source.campaign_name,
          recipient_id: recipientId,
          client_id: client.id,
          client_name: prettyName(client),
          yc_id: client.yc_id || null,
          transport: 'telegram',
          recipient: String(row.channel_user_id || ''),
          text: source.text
        });
      }

      if (mappedChannel === 'whatsapp' || mappedChannel === 'max') {
        const config = pickGreenConfig(mappedChannel);
        if (!config) continue;
        pushTarget(outputs, seen, {
          campaign_name: source.campaign_name,
          recipient_id: recipientId,
          client_id: client.id,
          client_name: prettyName(client),
          yc_id: client.yc_id || null,
          transport: mappedChannel,
          recipient: String(row.channel_user_id || ''),
          text: source.text,
          provider_url: buildProviderUrl(config)
        });
      }

      if (mappedChannel === 'sms') {
        const phone = normalizePhone(row.channel_user_id || client.phone);
        if (!phone) continue;
        pushTarget(outputs, seen, {
          campaign_name: source.campaign_name,
          recipient_id: recipientId,
          client_id: client.id,
          client_name: prettyName(client),
          yc_id: client.yc_id || null,
          transport: 'sms',
          recipient: phone,
          text: source.text,
          sms_basic_auth: smsBasicAuth,
          sms_sign: smsSign
        });
      }
    }

    if (requestedSet.has('telegram')) {
      for (const row of telegramUsers) {
        if (!canMessage(row)) continue;
        pushTarget(outputs, seen, {
          campaign_name: source.campaign_name,
          recipient_id: recipientId,
          client_id: client.id,
          client_name: prettyName(client),
          yc_id: client.yc_id || null,
          transport: 'telegram',
          recipient: String(row.user_id || ''),
          text: source.text
        });
      }
    }

    if (requestedSet.has('whatsapp')) {
      const config = pickGreenConfig('whatsapp');
      if (config) {
        for (const row of whatsappUsers) {
          if (!canMessage(row)) continue;
          pushTarget(outputs, seen, {
            campaign_name: source.campaign_name,
            recipient_id: recipientId,
            client_id: client.id,
            client_name: prettyName(client),
            yc_id: client.yc_id || null,
            transport: 'whatsapp',
            recipient: String(row.user_id || ''),
            text: source.text,
            provider_url: buildProviderUrl(config)
          });
        }
      }
    }

    if (requestedSet.has('max')) {
      const config = pickGreenConfig('max');
      if (config) {
        for (const row of maxUsers) {
          if (!canMessage(row)) continue;
          pushTarget(outputs, seen, {
            campaign_name: source.campaign_name,
            recipient_id: recipientId,
            client_id: client.id,
            client_name: prettyName(client),
            yc_id: client.yc_id || null,
            transport: 'max',
            recipient: String(row.user_id || ''),
            text: source.text,
            provider_url: buildProviderUrl(config)
          });
        }
      }
    }

    if (requestedSet.has('sms')) {
      const phone = normalizePhone(client.phone);
      if (phone) {
        pushTarget(outputs, seen, {
          campaign_name: source.campaign_name,
          recipient_id: recipientId,
          client_id: client.id,
          client_name: prettyName(client),
          yc_id: client.yc_id || null,
          transport: 'sms',
          recipient: phone,
          text: source.text,
          sms_basic_auth: smsBasicAuth,
          sms_sign: smsSign
        });
      }
    }

    continue;
  }

  const [telegramUsers, whatsappUsers, maxUsers] = await Promise.all([
    requestedSet.has('telegram')
      ? sbSelect('telegram_users', `select=user_id,tg_username,first_name,last_name,blocked,allow_marketing,can_message&user_id=eq.${encodeEq(recipientId)}&limit=1`)
      : Promise.resolve([]),
    requestedSet.has('whatsapp')
      ? sbSelect('whatsapp_users', `select=user_id,first_name,last_name,blocked,allow_marketing,can_message&user_id=eq.${encodeEq(recipientId)}&limit=1`)
      : Promise.resolve([]),
    requestedSet.has('max')
      ? sbSelect('max_users', `select=user_id,first_name,last_name,blocked,allow_marketing,can_message&user_id=eq.${encodeEq(recipientId)}&limit=1`)
      : Promise.resolve([])
  ]);

  for (const row of telegramUsers) {
    if (!canMessage(row)) continue;
    pushTarget(outputs, seen, {
      campaign_name: source.campaign_name,
      recipient_id: recipientId,
      client_id: null,
      client_name: prettyName(row),
      yc_id: null,
      transport: 'telegram',
      recipient: String(row.user_id || ''),
      text: source.text
    });
  }

  if (requestedSet.has('whatsapp')) {
    const config = pickGreenConfig('whatsapp');
    if (config) {
      for (const row of whatsappUsers) {
        if (!canMessage(row)) continue;
        pushTarget(outputs, seen, {
          campaign_name: source.campaign_name,
          recipient_id: recipientId,
          client_id: null,
          client_name: prettyName(row),
          yc_id: null,
          transport: 'whatsapp',
          recipient: String(row.user_id || ''),
          text: source.text,
          provider_url: buildProviderUrl(config)
        });
      }
    }
  }

  if (requestedSet.has('max')) {
    const config = pickGreenConfig('max');
    if (config) {
      for (const row of maxUsers) {
        if (!canMessage(row)) continue;
        pushTarget(outputs, seen, {
          campaign_name: source.campaign_name,
          recipient_id: recipientId,
          client_id: null,
          client_name: prettyName(row),
          yc_id: null,
          transport: 'max',
          recipient: String(row.user_id || ''),
          text: source.text,
          provider_url: buildProviderUrl(config)
        });
      }
    }
  }
}

return outputs;
})();

const body = $json.body ?? $json;
const params = body.params ?? {};
const filters = params.filters ?? {};

function normalizeChannel(value) {
  const raw = String(value ?? '').trim().toLowerCase();
  if (!raw || ['all', 'any', 'все', 'любой', 'любой канал'].includes(raw)) return '';
  const compact = raw.replace(/\s+/g, '').replace(/[_-]+/g, '');
  const map = {
    tg: 'telegram',
    telegram: 'telegram',
    телеграм: 'telegram',
    тг: 'telegram',
    whatsapp: 'whatsapp',
    wa: 'whatsapp',
    ватсап: 'whatsapp',
    ватсапп: 'whatsapp',
    max: 'max',
    макс: 'max',
    sms: 'sms',
    смс: 'sms',
    phone: 'sms',
    телефон: 'sms',
  };
  return map[compact] || '';
}

const recipientIds = Array.isArray(params.recipient_ids)
  ? params.recipient_ids.map((value) => String(value).trim()).filter(Boolean)
  : [];

if (!recipientIds.length) {
  throw new Error('recipient_ids is empty');
}

const requestedChannels = [];
for (const value of Array.isArray(params.channels) ? params.channels : []) {
  const channel = normalizeChannel(value);
  if (channel && !requestedChannels.includes(channel)) requestedChannels.push(channel);
}
for (const value of Array.isArray(params.transports) ? params.transports : []) {
  const channel = normalizeChannel(value);
  if (channel && !requestedChannels.includes(channel)) requestedChannels.push(channel);
}

const filterChannel = normalizeChannel(filters.channel);
if (filterChannel && !requestedChannels.includes(filterChannel)) {
  requestedChannels.push(filterChannel);
}

const transport = normalizeChannel(params.transport);
const frontendSendsTelegramAsDefault = transport === 'telegram' && !filterChannel && requestedChannels.length === 0;
if (transport && !frontendSendsTelegramAsDefault && !requestedChannels.includes(transport)) {
  requestedChannels.push(transport);
}

if (!requestedChannels.length) {
  requestedChannels.push('telegram', 'whatsapp', 'max', 'sms');
}

const text = String(params.text ?? '').trim();
if (!text) {
  throw new Error('text is empty');
}

return [{
  json: {
    org_uid: body.org_uid,
    action_code: body.action_code,
    role: body.role ?? null,
    client_time: body.client_time ?? null,
    campaign_name: String(params.campaign_name || 'Growice campaign'),
    campaign_type: String(params.campaign_type || 'manual'),
    segment: String(params.segment || 'Все получатели'),
    text,
    filters,
    recipients_count: Number(params.recipients_count || recipientIds.length),
    recipient_ids: recipientIds,
    requested_channels: requestedChannels
  }
}];

const campaign = $json;
const ids = Array.isArray(campaign.recipient_ids) ? campaign.recipient_ids : [];

return ids.map((id) => ({
  json: {
    ...campaign,
    recipient_id: String(id)
  }
}));
